#include <bits/stdc++.h>
using namespace std;

int main(){
    int T;
    scanf("%d",&T);
    while(T--){
        int n;
        scanf("%d",&n);
        vector<int> p(n+1);
        for(int i=1;i<=n;i++) scanf("%d",&p[i]);

        vector<pair<int,int>> edges(n-1);
        vector<vector<pair<int,int>>> adj(n+1);
        for(int i=0;i<n-1;i++){
            int u,v;
            scanf("%d%d",&u,&v);
            edges[i]={u,v};
            adj[u].push_back({v,i});
            adj[v].push_back({u,i});
        }

        // BFS tree from root=1
        vector<int> par(n+1,0), depth(n+1,0);
        vector<vector<int>> children(n+1);
        vector<int> bfs;
        vector<bool> vis(n+1,false);
        queue<int> q;
        q.push(1); vis[1]=true;
        while(!q.empty()){
            int u=q.front();q.pop(); bfs.push_back(u);
            for(auto [v,ei]:adj[u]) if(!vis[v]){
                vis[v]=true; par[v]=u; depth[v]=depth[u]+1;
                children[u].push_back(v);
                q.push(v);
            }
        }
        // LCA with binary lifting
        int LOG=1; while((1<<LOG)<=n) LOG++;
        vector<vector<int>> up(LOG, vector<int>(n+1,0));
        for(int i=1;i<=n;i++) up[0][i]=par[i];
        for(int k=1;k<LOG;k++) for(int i=1;i<=n;i++) up[k][i]=up[k-1][up[k-1][i]];

        auto lca=[&](int a,int b)->int{
            if(depth[a]<depth[b]) swap(a,b);
            int d=depth[a]-depth[b];
            for(int k=0;k<LOG;k++) if((d>>k)&1) a=up[k][a];
            if(a==b) return a;
            for(int k=LOG-1;k>=0;k--) if(up[k][a]!=up[k][b]){a=up[k][a];b=up[k][b];}
            return up[0][a];
        };
        auto next_on_path=[&](int from, int to)->int{
            int l=lca(from,to);
            if(from==to) return from;
            if(depth[from]>depth[l]) return par[from];
            // go toward to: find child of from on path to to
            int v=to;
            while(depth[v]>depth[from]+1) v=par[v];
            if(par[v]==from) return v;
            return par[from]; // shouldn't happen
        };

        // For edge index lookup
        map<pair<int,int>,int> edge_id;
        for(int i=0;i<n-1;i++){auto[u,v]=edges[i];edge_id[{u,v}]=i;edge_id[{v,u}]=i;}

        vector<vector<int>> results;
        for(int iter=0;iter<2*n&&iter<4000;iter++){
            bool done=true;
            for(int i=1;i<=n;i++) if(p[i]!=i){done=false;break;}
            if(done) break;
            vector<bool> used(n+1,false);
            vector<int> matching;
            vector<int> displaced;
            for(int i=1;i<=n;i++) if(p[i]!=i) displaced.push_back(i);
            // shuffle for variety? or sort by distance desc
            sort(displaced.begin(),displaced.end(),[&](int a,int b){return depth[a]+depth[p[a]]>depth[b]+depth[p[b]];});
            for(int i:displaced){
                if(used[i]||p[i]==i) continue;
                int nxt=next_on_path(i,p[i]);
                if(used[nxt]) continue;
                int ei=edge_id[{i,nxt}];
                used[i]=used[nxt]=true;
                matching.push_back(ei);
                swap(p[i],p[nxt]);
            }
            if(matching.empty()) break;
            results.push_back(matching);
        }
        printf("%d\n",(int)results.size());
        for(auto&m:results){printf("%d",(int)m.size());for(int ei:m) printf(" %d",ei+1);printf("\n");}
    }
}
